-- Frozen bilingual guitar catalog. The fixed system profile owns every basic diagram.
-- Each assertion deliberately divides by zero when its precondition is false.
SELECT 1 / (SELECT CASE WHEN EXISTS (SELECT 1 FROM languages WHERE code='en') AND EXISTS (SELECT 1 FROM languages WHERE code='pt_BR') AND NOT EXISTS (SELECT 1 FROM languages WHERE code NOT IN ('en','pt_BR','any')) THEN 1 ELSE 0 END) AS catalog_translations_required;
SELECT 1 / (SELECT CASE WHEN (NOT EXISTS (SELECT 1 FROM users WHERE id='77d0239a-8d28-5c95-bc6e-53d59f7f84a8' OR clerk_user_id='system:catalog')) OR EXISTS (SELECT 1 FROM users u JOIN languages l ON l.id=u.locale_id WHERE u.id='77d0239a-8d28-5c95-bc6e-53d59f7f84a8' AND u.clerk_user_id='system:catalog' AND u.role='admin' AND u.display_name='MotifPath Catalog' AND l.code='en') THEN 1 ELSE 0 END) AS system_catalog_profile_compatible;
SELECT 1 / (SELECT CASE WHEN (SELECT count(*) FROM instruments WHERE names IN ('{"en":"Guitar","pt_BR":"Violão"}'::jsonb,'{"en":"Electric guitar","pt_BR":"Guitarra elétrica"}'::jsonb)) <= 2 THEN 1 ELSE 0 END) AS unambiguous_catalog_instruments_required;
SELECT 1 / (SELECT CASE WHEN (SELECT count(*) FROM skills WHERE name='Scales' AND parent_id IS NULL) <= 1 AND (SELECT count(*) FROM concepts WHERE name='Fretboard patterns' AND parent_id IS NULL) <= 1 THEN 1 ELSE 0 END) AS unambiguous_catalog_classification_required;
SELECT 1 / (SELECT CASE WHEN (SELECT count(*) FROM skills WHERE name='Chords' AND parent_id IS NULL) <= 1 THEN 1 ELSE 0 END) AS unambiguous_skill_required;
SELECT 1 / (SELECT CASE WHEN (SELECT count(*) FROM skills WHERE name='Arpeggios' AND parent_id IS NULL) <= 1 THEN 1 ELSE 0 END) AS unambiguous_skill_required;
SELECT 1 / (SELECT CASE WHEN (SELECT count(*) FROM skills WHERE name='Improvisation' AND parent_id IS NULL) <= 1 THEN 1 ELSE 0 END) AS unambiguous_skill_required;
SELECT 1 / (SELECT CASE WHEN (SELECT count(*) FROM skills WHERE name='Fretboard navigation' AND parent_id IS NULL) <= 1 THEN 1 ELSE 0 END) AS unambiguous_skill_required;
